INSERT INTO research_exposure_blocked_signals (
    evaluation_id, fixture_id, fixture_observation_id, config_fingerprint,
    reason_code, blocked_at, open_exposure_minor, proposed_stake_minor,
    max_open_exposure_minor, capture_source
)
SELECT
    h.evaluation_id,
    e.fixture_id,
    p.fixture_observation_id,
    NULL,
    'MAX_OPEN_EXPOSURE_EXCEEDED',
    h.blocked_at,
    h.open_exposure_minor,
    h.proposed_stake_minor,
    h.max_open_exposure_minor,
    'RAILWAY_LOG_BACKFILL'
FROM historical h
JOIN value_evaluations e ON e.evaluation_id = h.evaluation_id
JOIN fixture_predictions p ON p.prediction_id = e.prediction_id
ON CONFLICT (evaluation_id) DO NOTHING;
),
    fixture_id TEXT NOT NULL CHECK (length(trim(fixture_id)) > 0),
    fixture_observation_id TEXT NOT NULL
        CHECK (fixture_observation_id ~ '^fixture-observation-v1:[0-9a-f]{64}
    reason_code TEXT NOT NULL CHECK (reason_code = 'MAX_OPEN_EXPOSURE_EXCEEDED'),
    blocked_at TIMESTAMPTZ NOT NULL,
    open_exposure_minor BIGINT NOT NULL CHECK (open_exposure_minor >= 0),
    proposed_stake_minor BIGINT NOT NULL CHECK (proposed_stake_minor > 0),
    max_open_exposure_minor BIGINT NOT NULL CHECK (max_open_exposure_minor > 0),
    capture_source TEXT NOT NULL CHECK (capture_source IN ('LIVE_GATE', 'RAILWAY_LOG_BACKFILL')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (fixture_observation_id, fixture_id)
        REFERENCES fixture_observations(fixture_observation_id, fixture_id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_research_exposure_blocked_time
    ON research_exposure_blocked_signals (blocked_at DESC, evaluation_id);
CREATE INDEX idx_research_exposure_blocked_fixture
    ON research_exposure_blocked_signals (fixture_id, blocked_at, evaluation_id);

CREATE FUNCTION reject_research_signal_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'research exposure-blocked signals are append-only';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER research_exposure_blocked_signals_append_only
    BEFORE UPDATE OR DELETE ON research_exposure_blocked_signals
    FOR EACH ROW EXECUTE FUNCTION reject_research_signal_mutation();

